<script lang="ts">
 import {onMount} from 'svelte';import {api,clearLegacyTokens,getSession,type Kind,type SessionUser} from './api';import ContentManager from './ContentManager.svelte';import Operations from './Operations.svelte';import Member from './Member.svelte';
 import './console.css';
 let user:SessionUser|null=null,allowRegistration=true,loading=true,error='',account='',password='',username='',email='',register=false,busy=false,view='overview',member=false,menuOpen=false,dark=false;
 const nav=[['overview','概览','01'],['posts','文章','02'],['messages','留言审核','03'],['anime','追番','04'],['diary','日记','05'],['albums','相册','06'],['media','媒体库','07'],['mirror','镜像同步','08']];
 const memberNav=[['overview','我的空间','01'],['profile','个人资料','02'],['messages','我的留言','03'],['favorites','我的收藏','04'],['history','阅读历史','05']];
 let counts:{kind:Kind;total:number}[]=[];
 async function session(){loading=true;try{clearLegacyTokens();const state=await getSession();allowRegistration=state.allowRegistration;if(!allowRegistration)register=false;user=state.authenticated?state.user:null;}catch{user=null;}finally{loading=false;}if(user?.role==='ADMIN'&&!member)void stats();}
 async function stats(){try{counts=await Promise.all((['posts','anime','diary','albums'] as Kind[]).map(async kind=>({kind,total:(await api<{meta:{total:number}}>(`/content/manage/${kind}?pageSize=1`)).meta.total})));}catch(e){error=String(e);}}
 onMount(()=>{member=location.pathname.startsWith('/user');view=new URLSearchParams(location.search).get('view')??(member?location.pathname.split('/')[2]||'overview':'overview');if(!(member?memberNav:nav).some(n=>n[0]===view))view='overview';dark=localStorage.getItem('axis-console-theme')==='dark';void session();});
 async function login(){busy=true;error='';try{const result=await api<{user:SessionUser}>('/auth/'+(register?'register':'login'),'POST',register?{username,email,password}:{account,password},{'X-Axis-Session-Mode':'cookie'});clearLegacyTokens();user=result.user;password='';if(user?.role!=='ADMIN')member=true;await session();}catch(e){error=String(e instanceof Error?e.message:e);}finally{busy=false;}}
 function canLeave(){return window.dispatchEvent(new Event('axis:before-leave',{cancelable:true}));}
 async function logout(){if(!canLeave())return;try{await api('/auth/logout','POST');}catch{}clearLegacyTokens();user=null;}
 function select(key:string){if(key===view||!canLeave())return;view=key;menuOpen=false;history.replaceState({},'',`${member?'/user/':'/admin/'}?view=${key}`);}
 function theme(){dark=!dark;localStorage.setItem('axis-console-theme',dark?'dark':'light');}
</script>
<div class="axis-console" class:theme-dark={dark}>
{#if loading}<div class="loading-screen"><span class="wordmark">AXIS<span> / </span></span><p>正在读取你的空间…</p></div>
{:else if !user}<main class="login-layout"><section class="login-story"><a class="wordmark" href="/">AXIS<span> / </span></a><div><p class="eyebrow">A SPACE FOR YOUR IDEAS</p><h1>记录生活，<br/>让想法生长。</h1><p>文章、影像与日常，<br/>在这里有序归档。</p></div><small>STAR BLOG · CONTENT STUDIO</small></section><section class="login-form panel"><p class="eyebrow">WELCOME BACK</p><h2>{register?'创建账户':'进入你的空间'}</h2><p class="muted">使用博客账户登录。</p>{#if error}<p class="error" role="alert">{error}</p>{/if}<form onsubmit={e=>{e.preventDefault();void login();}}>{#if register}<label>用户名<input bind:value={username} required minlength="3" autocomplete="username"/></label><label>邮箱<input bind:value={email} type="email" required autocomplete="email"/></label>{:else}<label>用户名或邮箱<input bind:value={account} required autocomplete="username"/></label>{/if}<label>密码<input bind:value={password} type="password" required minlength="8" autocomplete={register?'new-password':'current-password'}/></label><button class="primary" disabled={busy}>{busy?'请稍候…':register?'注册':'登录'}</button></form>{#if allowRegistration}<button class="text-button" onclick={()=>{register=!register;error='';}}>{register?'已有账户？登录':'还没有账户？注册'}</button>{/if}<a href="/">返回博客 ↗</a></section></main>
{:else if !member&&user.role!=='ADMIN'}<main class="panel"><h1>这是管理员空间</h1><a class="button primary" href="/user/">进入个人中心</a><button onclick={()=>{void logout();}}>退出登录</button></main>
{:else}<div class="console-grid"><aside class="sidebar" class:open={menuOpen}><a class="wordmark" href="/">AXIS<span> / </span></a><p class="sidebar-caption">{member?'PERSONAL SPACE':'CONTENT STUDIO'}</p><nav aria-label="管理导航">{#each member?memberNav:nav as [key,label,num]}<button class:active={view===key} onclick={()=>select(key)}><span>{num}</span>{label}</button>{/each}</nav><div class="sidebar-footer"><a href="/">↗ 访问博客</a>{#if user.role==='ADMIN'}<a href={member?'/admin/':'/user/'}>{member?'管理员后台':'个人中心'}</a>{/if}<small>一个属于你的数字花园。</small></div></aside><div class="workspace"><header class="topbar"><button class="mobile-toggle" aria-expanded={menuOpen} aria-label="展开导航" onclick={()=>menuOpen=!menuOpen}>☰</button><div class="breadcrumb">{member?'个人中心':'工作空间'} <span>/</span> {(member?memberNav:nav).find(n=>n[0]===view)?.[1]}</div><div class="toolbar"><button onclick={theme}>{dark?'浅色':'深色'}</button><span class="user-name">{user.username}</span><button onclick={()=>{void logout();}}>退出</button></div></header><main class="workspace-main">{#if error}<p class="error" role="alert">{error}</p>{/if}{#key `${member}:${view}`}{#if member}<Member {view}/>{:else if view==='overview'}<div class="welcome"><p class="eyebrow">YOUR WORKSPACE, AT A GLANCE</p><h1>把今天，记录下来。</h1><p class="muted">欢迎回来，{user.username}。从一篇新文章开始，或整理最近的生活。</p><button class="primary" onclick={()=>select('posts')}>打开文章管理 →</button></div><div class="metrics">{#each counts as count}<button onclick={()=>select(count.kind)}><span>{{posts:'文章',anime:'追番',diary:'日记',albums:'相册'}[count.kind]}</span><strong>{count.total}</strong><small>管理内容 ↗</small></button>{/each}</div><section class="panel"><h2>发布流程</h2><div class="publishing-steps"><div><b>01</b><h3>写作与整理</h3><p>保存编辑稿，预览内容。已公开的版本保持稳定。</p></div><div><b>02</b><h3>发布到主站</h3><p>点击发布，新内容立即进入博客与搜索。</p></div><div><b>03</b><h3>同步静态镜像</h3><p>构建完成后核对线上版本，也可以在同步页重试。</p></div></div></section>{:else if ['posts','anime','diary','albums'].includes(view)}<ContentManager kind={view as Kind}/>{:else}<Operations {view}/>{/if}{/key}</main><footer class="workspace-footer">AXIS / STAR BLOG <span>记录 · 创作 · 分享</span></footer></div></div>{/if}
</div>
